import{_ as o,o as n,c as t,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"G1 — Authentication (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g1-auth/spec.md","filePath":"mobile/features/g1-auth/spec.md"}'),i={name:"mobile/features/g1-auth/spec.md"};function a(r,e,d,l,s,h){return n(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="g1-—-authentication-mobile" tabindex="-1">G1 — Authentication (Mobile) <a class="header-anchor" href="#g1-—-authentication-mobile" aria-label="Permalink to &quot;G1 — Authentication (Mobile)&quot;">​</a></h1><p>&gt; <a href="./../mobile-app-plan.html">&lt;&lt; Về plan tổng</a> &gt; <a href="./plan.html">plan.md</a> | <a href="./task.html">task.md</a> | <a href="./test.html">test.md</a> &gt; Nguồn tham chiếu đã đọc thật (không đoán): &gt; - <code>brandhub-business-service/src/main/java/com/brandhub/business/controller/AuthController.java</code> &gt; - <code>brandhub-business-service/src/main/java/com/brandhub/business/controller/GoogleOAuthController.java</code> &gt; - <code>brandhub-business-service/src/main/java/com/brandhub/business/dto/request/*.java</code>, <code>dto/response/*.java</code> &gt; - <code>brandhub-business-service/src/main/java/com/brandhub/business/exception/ErrorCode.java</code> &gt; - <code>brandhub-business-service/src/main/java/com/brandhub/business/config/OAuthProperties.java</code> &gt; - <code>brandhub-infrastructure/docs/ba/02-authentication-profile.md</code> &gt; - <code>brandhub-web/src/pages/auth/LoginPage.tsx</code>, <code>OAuthCallbackPage.tsx</code>, <code>hooks/useOAuthCallback.ts</code> &gt; - <code>brandhub-mobile-app/README.md</code>, <code>package.json</code></p><h2 id="_1-muc-tieu-pham-vi" tabindex="-1">1. Mục tiêu &amp; phạm vi <a class="header-anchor" href="#_1-muc-tieu-pham-vi" aria-label="Permalink to &quot;1. Mục tiêu &amp; phạm vi&quot;">​</a></h2><p>G1 đưa mobile từ &quot;chưa có auth thật&quot; lên ngang hàng với web cho các luồng auth chính: Sign In Email, Sign In Google OAuth, Forgot/Reset Password, OTP Verification (dùng chung), 2FA Verify (nếu user đã bật), Sign Out. <strong>Register (Sign Up) được đưa vào G1</strong> vì OTP verification là dependency chung và app cần một điểm vào cho user hoàn toàn mới.</p><p><strong>Phạm vi G1 trên mobile:</strong></p><ul><li>Login (email/password), Register + verify OTP, Forgot Password, Reset Password (qua deep link), Logout.</li><li>Sign In Google OAuth — bám theo flow backend-driven hiện có của web, chuyển sang pattern <code>expo-auth-session</code> phù hợp Expo managed.</li><li>2FA Verify màn hình (nhập mã OTP) khi <code>login</code> trả về <code>requireTwoFactor</code>. <strong>Không làm màn hình Setup 2FA / bật 2FA mới trên mobile ở G1</strong> — đó thuộc Settings, để domain sau.</li><li>Change Password, Deactivate Account, link/unlink phone, 2FA setup/disable: <strong>không làm ở G1</strong> (xem mục 7).</li></ul><p><strong>Khoảng cách với web (parity gap) cần biết trước khi build:</strong></p><ul><li>BA doc ghi rõ: <em>&quot;3.2.3 — Ghi chú hiện trạng: login hiện tại theo báo cáo vẫn chưa chạy được — cần coi lại toàn bộ flow (không chỉ là feature mới, là bug fix trên flow cũ)&quot;</em> (<code>docs/ba/02-authentication-profile.md</code> dòng 17). Nghĩa là Google OAuth trên web bản thân nó đang được coi là chưa ổn định; mobile implement theo cùng API backend nên rủi ro lỗi tương tự có thể lặp lại, cần test kỹ trước khi coi G1 xong.</li><li>Web dùng flow redirect trình duyệt thuần (backend redirect sang Google, Google redirect lại backend, backend redirect về frontend kèm token trên URL fragment <code>#token=...</code>). Mobile không có &quot;URL fragment&quot; theo nghĩa browser history như web — cần dùng <code>expo-web-browser</code> (<code>WebBrowser.openAuthSessionAsync</code>) để mở phiên trình duyệt trong app và bắt lại redirect về qua custom scheme deep link, xem mục 4.3.</li></ul><h2 id="_2-fr-tham-chieu" tabindex="-1">2. FR tham chiếu <a class="header-anchor" href="#_2-fr-tham-chieu" aria-label="Permalink to &quot;2. FR tham chiếu&quot;">​</a></h2><p>Theo <code>docs/ba/02-authentication-profile.md</code>:</p><table tabindex="0"><thead><tr><th>FR</th><th>Tên</th><th>Tóm tắt 1 dòng</th></tr></thead><tbody><tr><td>3.2.1</td><td>Sign Up</td><td>Đăng ký email/password, bắt buộc verify OTP; email so khớp không phân biệt hoa/thường ở local-part</td></tr><tr><td>3.2.2</td><td>Sign In With Email</td><td>Đăng nhập email/phone + password, không cần OTP lại</td></tr><tr><td>3.2.3</td><td>Sign In with Google OAuth</td><td>OAuth qua Google — hiện trạng được BA ghi là chưa chạy ổn, cần test kỹ</td></tr><tr><td>3.2.4</td><td>Reset Password</td><td>Quên mật khẩu → gửi link hoặc OTP tới email → đổi mật khẩu mới</td></tr><tr><td>3.2.6</td><td>OTP Verification</td><td>Màn hình nhập OTP dùng chung cho Sign Up / Reset Password / 2FA</td></tr><tr><td>3.2.7</td><td>Two-Factor Authentication (TOTP)</td><td>Chỉ còn scan QR + nhập OTP (đã bỏ copy secret key và backup codes)</td></tr><tr><td>3.2.8</td><td>Sign Out</td><td>Đăng xuất, phải lưu &quot;last used platform&quot; để gợi ý nút đăng nhập lần sau</td></tr></tbody></table><p>Không thuộc G1 nhưng có API đã tồn tại ở backend, ghi nhận để không trùng lặp sau: 3.2.5 Change Password, 3.2.9 Deactivate Account, 2FA setup/disable, link/unlink phone &amp; OAuth.</p><h2 id="_3-api-can-dung" tabindex="-1">3. API cần dùng <a class="header-anchor" href="#_3-api-can-dung" aria-label="Permalink to &quot;3. API cần dùng&quot;">​</a></h2><p>Base path: <code>/api/v1/auth</code> (từ <code>AuthController.java</code>). Tất cả response bọc trong <code>ApiResponse&lt;T&gt;</code> (có <code>requestId</code>). Lỗi dùng <code>ErrorCode</code> enum ở <code>exception/ErrorCode.java</code>.</p><h3 id="_3-1-register-—-post-api-v1-auth-register" tabindex="-1">3.1 Register — <code>POST /api/v1/auth/register</code> <a class="header-anchor" href="#_3-1-register-—-post-api-v1-auth-register" aria-label="Permalink to &quot;3.1 Register — `POST /api/v1/auth/register`&quot;">​</a></h3><ul><li>Request <code>RegisterRequest</code>: <code>{ email: string (email, bắt buộc), password: string (bắt buộc, &gt;=8 ký tự, phải có ít nhất 1 số), fullName: string (bắt buộc) }</code></li><li>Response <code>201 Created</code>, <code>RegisterResponse</code>: <code>{ userId: string (UUID) }</code></li><li>Sau khi register thành công, flow bắt buộc chuyển sang OTP Verification (không tự login).</li></ul><h3 id="_3-2-verify-otp-—-post-api-v1-auth-verify-otp" tabindex="-1">3.2 Verify OTP — <code>POST /api/v1/auth/verify-otp</code> <a class="header-anchor" href="#_3-2-verify-otp-—-post-api-v1-auth-verify-otp" aria-label="Permalink to &quot;3.2 Verify OTP — `POST /api/v1/auth/verify-otp`&quot;">​</a></h3><ul><li>Request <code>VerifyOtpRequest</code>: <code>{ email: string (email), otpCode: string (đúng 6 ký tự) }</code></li><li>Response: <code>ApiResponse&lt;Void&gt;</code> — không có body data, chỉ <code>requestId</code>.</li><li>Dùng chung cho luồng Sign Up (kích hoạt email) và các luồng khác cần OTP tương tự.</li></ul><h3 id="_3-3-resend-otp-—-post-api-v1-auth-resend-otp" tabindex="-1">3.3 Resend OTP — <code>POST /api/v1/auth/resend-otp</code> <a class="header-anchor" href="#_3-3-resend-otp-—-post-api-v1-auth-resend-otp" aria-label="Permalink to &quot;3.3 Resend OTP — `POST /api/v1/auth/resend-otp`&quot;">​</a></h3><ul><li>Request: <code>ForgotPasswordRequest</code> shape — thực chất chỉ <code>{ email: string }</code> (controller dùng lại DTO <code>ForgotPasswordRequest</code> cho resend).</li><li>Response: <code>ApiResponse&lt;Void&gt;</code>.</li></ul><h3 id="_3-4-login-—-post-api-v1-auth-login" tabindex="-1">3.4 Login — <code>POST /api/v1/auth/login</code> <a class="header-anchor" href="#_3-4-login-—-post-api-v1-auth-login" aria-label="Permalink to &quot;3.4 Login — `POST /api/v1/auth/login`&quot;">​</a></h3><ul><li>Request <code>LoginRequest</code>: <code>{ identifier: string (bắt buộc — email hoặc phone, theo placeholder web &quot;hello@company.com / 0912 345 678&quot;), password: string (bắt buộc) }</code></li><li>Response <code>LoginResponse</code>:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{ accessToken: string|null, refreshToken: string|null, tokenType: &quot;Bearer&quot;|null,</span></span>\n<span class="line"><span>  expiresIn: number (giây), requireTwoFactor: boolean, twoFactorToken: string|null }</span></span></code></pre></div><ul><li>Nếu <code>requireTwoFactor === true</code>: <code>accessToken</code>/<code>refreshToken</code> là <code>null</code>, chỉ có <code>twoFactorToken</code> — <strong>chưa đăng nhập xong</strong>, phải điều hướng sang màn 2FA Verify, lưu <code>twoFactorToken</code> tạm (web dùng <code>sessionStorage</code>, mobile dùng state trong memory/Zustand, không cần SecureStore vì token này sống rất ngắn).</li><li>Nếu login thành công bình thường: có <code>accessToken</code> + <code>refreshToken</code> đầy đủ.</li></ul></li><li>Response headers: server set cookie <code>refreshToken</code> (HttpOnly) — <strong>mobile không dùng được cookie theo cách này</strong> (không có browser cookie jar mặc định dùng chung với Axios/fetch trừ khi tự quản lý) → mobile phải lấy <code>refreshToken</code> từ <strong>response body</strong>, không trông chờ cookie. Cần xác nhận với backend rằng field <code>refreshToken</code> trong body luôn có giá trị khi gọi từ mobile (không bị set <code>null</code> với giả định FE luôn đọc cookie) — xem mục 8 rủi ro.</li><li>Error cases: <code>INVALID_CREDENTIALS</code> (401), <code>ACCOUNT_LOCKED</code> (403, khóa tạm do nhiều lần sai), <code>ACCOUNT_SUSPENDED</code> (403).</li></ul><h3 id="_3-5-refresh-token-—-post-api-v1-auth-refresh" tabindex="-1">3.5 Refresh Token — <code>POST /api/v1/auth/refresh</code> <a class="header-anchor" href="#_3-5-refresh-token-—-post-api-v1-auth-refresh" aria-label="Permalink to &quot;3.5 Refresh Token — `POST /api/v1/auth/refresh`&quot;">​</a></h3><ul><li>Request <code>RefreshTokenRequest</code>: <code>{ refreshToken: string }</code> — gửi trong body (vì mobile không có cookie).</li><li>Response: <code>LoginResponse</code> (giống Login, có <code>accessToken</code> mới + <code>refreshToken</code> mới — rotate).</li><li>Error: <code>REFRESH_TOKEN_INVALID</code> (401) nếu thiếu/rỗng cả cookie và body; <code>REFRESH_TOKEN_BLACKLISTED</code> (401) nếu đã bị revoke (ví dụ sau logout).</li><li>Đây chính là endpoint mà Axios interceptor hiện có trong README (&quot;Auto-refresh on 401&quot;) phải gọi.</li></ul><h3 id="_3-6-forgot-password-—-post-api-v1-auth-forgot-password" tabindex="-1">3.6 Forgot Password — <code>POST /api/v1/auth/forgot-password</code> <a class="header-anchor" href="#_3-6-forgot-password-—-post-api-v1-auth-forgot-password" aria-label="Permalink to &quot;3.6 Forgot Password — `POST /api/v1/auth/forgot-password`&quot;">​</a></h3><ul><li>Request <code>ForgotPasswordRequest</code>: <code>{ email: string (email) }</code></li><li>Response: <code>ApiResponse&lt;Void&gt;</code>.</li><li>Theo BA: gửi <strong>link đổi mật khẩu HOẶC mã OTP</strong> tới email — cần xác nhận với backend hình thức thực tế gửi là gì (link kèm token trong URL, hay OTP 6 số) để thiết kế đúng màn Reset Password (xem mục 8).</li></ul><h3 id="_3-7-reset-password-—-post-api-v1-auth-reset-password" tabindex="-1">3.7 Reset Password — <code>POST /api/v1/auth/reset-password</code> <a class="header-anchor" href="#_3-7-reset-password-—-post-api-v1-auth-reset-password" aria-label="Permalink to &quot;3.7 Reset Password — `POST /api/v1/auth/reset-password`&quot;">​</a></h3><ul><li>Request <code>ResetPasswordRequest</code>: <code>{ token: string (bắt buộc), newPassword: string (bắt buộc, &gt;=8 ký tự, có số) }</code></li><li>Response: <code>ApiResponse&lt;Void&gt;</code>.</li><li><code>token</code> lấy từ link trong email (deep link) hoặc từ OTP nhập tay — tùy cách backend thực hiện (xem mục 8).</li></ul><h3 id="_3-8-google-oauth" tabindex="-1">3.8 Google OAuth <a class="header-anchor" href="#_3-8-google-oauth" aria-label="Permalink to &quot;3.8 Google OAuth&quot;">​</a></h3><p>Ba endpoint theo <code>GoogleOAuthController.java</code>, <strong>đều là GET trả <code>302 redirect</code>, không phải JSON API thông thường</strong>:</p><ul><li><code>GET /api/v1/auth/oauth/google?client=mobile</code> — <strong>mobile phải thêm query <code>client=mobile</code></strong> (backend đã hỗ trợ, mục 8 câu 1) để callback redirect về deep link <code>brandhub://oauth-callback</code> thay vì web <code>frontendUrl</code>. Thiếu param này = mặc định hành vi web, mobile không bắt được redirect.</li><li><code>GET /api/v1/auth/oauth/google/callback</code> (và alias <code>/login/oauth2/code/google</code>) — Google gọi lại endpoint này sau khi user đồng ý; backend exchange code lấy token, rồi <strong>redirect tiếp về <code>{frontendUrl}/oauth-callback#token={accessToken}</code></strong> (token nằm trên URL fragment) kèm set cookie <code>refreshToken</code> HttpOnly.</li><li><code>GET /api/v1/auth/oauth/google/link?token={jwt}</code> — link-mode, user đã đăng nhập muốn gắn thêm Google vào account (không dùng ở G1 mobile — thuộc Settings/Connections).</li></ul><p>Trường hợp lỗi, backend redirect về frontend kèm query <code>?error=...</code>:</p><ul><li><code>error=oauth_failed</code> — lỗi chung (code invalid, exchange fail, ...).</li><li><code>error=ACCOUNT_SUSPENDED</code> — tài khoản bị khóa, redirect về <code>/oauth-callback?error=ACCOUNT_SUSPENDED</code> (có message riêng, không dùng toast chung — theo comment trong code dòng 75-79 <code>GoogleOAuthController.java</code>).</li><li><code>error=OAUTH_EMAIL_MISMATCH</code> / <code>error=OAUTH_ALREADY_LINKED</code> — chỉ xảy ra ở link-mode, redirect về <code>/settings/connections</code>, không liên quan luồng Sign In ở G1.</li></ul><p><code>frontendUrl</code> lấy từ <code>AppProperties</code> (config phía backend) — với mobile, backend cần một <code>redirectUri</code>/<code>frontendUrl</code> riêng trỏ về deep link scheme của app (ví dụ <code>brandhub://oauth-callback</code>) khi request đến từ mobile, <strong>hiện backend chỉ có 1 <code>frontendUrl</code> cấu hình cứng cho web</strong> → cần backend thêm cấu hình hoặc tham số phân biệt nguồn gọi (web vs mobile). Đây là việc phải làm ở backend trước khi mobile implement được, ghi nhận ở mục 8.</p><p>Sau khi có <code>accessToken</code> từ fragment, mobile phải tự gọi tiếp <code>GET /api/v1/users/me</code> (hoặc <code>GET /api/v1/auth/me</code>, xem dưới) để lấy profile đầy đủ, giống hệt cách <code>useOAuthCallback.ts</code> làm ở web (dòng 52 — gọi <code>authService.getProfile()</code> sau khi có token).</p><h3 id="_3-9-me-lay-profile-toi-gian-auth-—-get-api-v1-auth-me" tabindex="-1">3.9 Me (lấy profile tối giản auth) — <code>GET /api/v1/auth/me</code> <a class="header-anchor" href="#_3-9-me-lay-profile-toi-gian-auth-—-get-api-v1-auth-me" aria-label="Permalink to &quot;3.9 Me (lấy profile tối giản auth) — `GET /api/v1/auth/me`&quot;">​</a></h3><ul><li>Header: <code>Authorization: Bearer {accessToken}</code>.</li><li>Response <code>MeResponse</code>: <code>{ userId, email, phone, hasPassword: boolean, linkedProviders: OAuthProvider[], twoFactorEnabled: boolean }</code>.</li><li>Lưu ý: đây KHÔNG phải endpoint Profile đầy đủ (fullName, avatar, role, workspaceId) mà web <code>LoginPage.tsx</code> dùng (<code>profileRes.data.data</code> có <code>fullName</code>, <code>role</code>, <code>workspaceId</code>, <code>avatarUrl</code> — chắc chắn gọi <code>/api/v1/users/me</code> ở service khác, không phải <code>/api/v1/auth/me</code>). <strong>Mobile sau khi login cũng phải gọi endpoint Users Profile thật (ngoài phạm vi G1, thuộc domain Profile) để có đủ field hiển thị</strong> — G1 chỉ cần đảm bảo lưu đúng token, verify qua <code>/auth/me</code> là optional health-check.</li></ul><h3 id="_3-10-2fa-verify-—-post-api-v1-auth-2fa-verify" tabindex="-1">3.10 2FA Verify — <code>POST /api/v1/auth/2fa/verify</code> <a class="header-anchor" href="#_3-10-2fa-verify-—-post-api-v1-auth-2fa-verify" aria-label="Permalink to &quot;3.10 2FA Verify — `POST /api/v1/auth/2fa/verify`&quot;">​</a></h3><ul><li>Request <code>TwoFactorVerifyRequest</code>: <code>{ twoFactorToken: string, code: string (đúng 6 ký tự) }</code></li><li>Response: <code>LoginResponse</code> đầy đủ (giống Login thành công) — set cookie refresh (mobile vẫn lấy từ body).</li><li>Dùng khi bước Login trả <code>requireTwoFactor: true</code>.</li></ul><h3 id="_3-11-logout-—-post-api-v1-auth-logout" tabindex="-1">3.11 Logout — <code>POST /api/v1/auth/logout</code> <a class="header-anchor" href="#_3-11-logout-—-post-api-v1-auth-logout" aria-label="Permalink to &quot;3.11 Logout — `POST /api/v1/auth/logout`&quot;">​</a></h3><ul><li>Header: <code>Authorization: Bearer {accessToken}</code> (bắt buộc, thiếu → 401 <code>INVALID_CREDENTIALS</code>).</li><li>Body (mobile <strong>bắt buộc</strong> gửi, web vẫn dùng cookie): <code>{ refreshToken: string }</code> — backend đã sửa (mục 8 câu 3b) để nhận <code>RefreshTokenRequest</code> qua body, ưu tiên cookie nếu có, fallback đọc body nếu không — mobile phải gửi field này để backend revoke đúng token.</li><li>Response: <code>ApiResponse&lt;Void&gt;</code>.</li><li>Theo FR 3.2.8: phải lưu &quot;last used platform&quot; (email hay Google) — đây là <strong>client-side local state</strong> (không thấy field nào trong <code>MeResponse</code>/<code>LoginResponse</code> lưu việc này phía backend), nên mobile tự lưu vào AsyncStorage/SecureStore non-sensitive key, không cần API riêng.</li></ul><h2 id="_4-luong-man-hinh-screen-flows" tabindex="-1">4. Luồng màn hình (screen flows) <a class="header-anchor" href="#_4-luong-man-hinh-screen-flows" aria-label="Permalink to &quot;4. Luồng màn hình (screen flows)&quot;">​</a></h2><h3 id="_4-1-login-screen" tabindex="-1">4.1 Login Screen <a class="header-anchor" href="#_4-1-login-screen" aria-label="Permalink to &quot;4.1 Login Screen&quot;">​</a></h3><ol><li>Form 2 input: <code>identifier</code> (email hoặc phone — placeholder giống web &quot;<a href="mailto:hello@company.com" target="_blank" rel="noreferrer">hello@company.com</a> / 0912 345 678&quot;), <code>password</code>.</li><li>Nút &quot;Đăng nhập&quot; → gọi <code>POST /auth/login</code>.</li><li>Loading state: disable nút + spinner trong lúc chờ.</li><li>Kết quả: <ul><li><code>requireTwoFactor === true</code> → lưu <code>twoFactorToken</code> vào state tạm, điều hướng <code>TwoFactorVerify</code> screen.</li><li>Thành công: lưu <code>accessToken</code>/<code>refreshToken</code> vào <code>expo-secure-store</code>, điều hướng vào app chính (Dashboard) theo redirect đã lưu nếu có (tương đương <code>consumeAuthRedirect()</code> ở web).</li></ul></li><li>Lỗi: toast theo <code>ErrorCode</code> — <code>INVALID_CREDENTIALS</code> → &quot;Email hoặc mật khẩu không đúng&quot;; <code>ACCOUNT_LOCKED</code> → &quot;Tài khoản tạm khóa do đăng nhập sai nhiều lần&quot;; <code>ACCOUNT_SUSPENDED</code> → &quot;Tài khoản đã bị khóa&quot;.</li><li>Link &quot;Quên mật khẩu?&quot; → <code>ForgotPassword</code> screen.</li><li>Nút &quot;Đăng nhập với Google&quot; → trigger flow 4.3.</li><li>Link chuyển sang <code>Register</code> screen.</li><li>Nếu app đã lưu &quot;last used platform&quot; = Google (FR 3.2.8), hiển thị nút Google nổi bật hơn (ví dụ đặt trên cùng, hoặc badge &quot;lần trước bạn dùng Google&quot;).</li></ol><h3 id="_4-2-register-screen" tabindex="-1">4.2 Register Screen <a class="header-anchor" href="#_4-2-register-screen" aria-label="Permalink to &quot;4.2 Register Screen&quot;">​</a></h3><ol><li>Form: <code>email</code>, <code>password</code> (hiển thị rule validate: &gt;=8 ký tự + có số, tương tự <code>PasswordStrengthMeter.tsx</code> ở web), <code>fullName</code>.</li><li>Submit → <code>POST /auth/register</code> → nhận <code>userId</code>.</li><li>Điều hướng ngay sang <code>VerifyOtp</code> screen, truyền kèm <code>email</code> đã đăng ký (OTP được gửi tới email đó).</li><li>Không tự động login sau register — phải verify OTP xong, rồi quay lại Login để đăng nhập tay (giống hành vi &quot;Sign Up khác Sign In — bắt buộc OTP&quot; ở BA 3.2.1 vs 3.2.2).</li></ol><h3 id="_4-3-verifyotp-screen-dung-chung" tabindex="-1">4.3 VerifyOtp Screen (dùng chung) <a class="header-anchor" href="#_4-3-verifyotp-screen-dung-chung" aria-label="Permalink to &quot;4.3 VerifyOtp Screen (dùng chung)&quot;">​</a></h3><ol><li>Nhận tham số <code>email</code> + <code>purpose</code> (context: <code>register</code> | <code>forgotPassword</code> — chỉ ảnh hưởng UI text, API giống nhau).</li><li>6 ô nhập OTP (hoặc 1 input numeric maxLength=6).</li><li>Submit → <code>POST /auth/verify-otp</code> với <code>{ email, otpCode }</code>.</li><li>Nút &quot;Gửi lại mã&quot; → <code>POST /auth/resend-otp</code> với <code>{ email }</code>, có cooldown (ví dụ 30-60s đếm ngược ở client — không thấy rate-limit cụ thể từ BA, cần xác nhận, xem mục 8).</li><li>Lỗi: <code>OTP_INVALID</code> → &quot;Mã không đúng hoặc đã hết hạn&quot;; <code>OTP_TOO_MANY_ATTEMPTS</code> → &quot;Nhập sai quá nhiều lần, hãy gửi lại mã mới&quot;.</li><li>Thành công: nếu <code>purpose === register</code> → điều hướng về Login kèm toast &quot;Xác thực thành công, hãy đăng nhập&quot;; nếu <code>purpose === forgotPassword</code> → luồng Reset Password dùng OTP đã verify (xem 4.5 nếu backend chọn nhánh OTP thay vì link).</li></ol><h3 id="_4-4-forgotpassword-screen" tabindex="-1">4.4 ForgotPassword Screen <a class="header-anchor" href="#_4-4-forgotpassword-screen" aria-label="Permalink to &quot;4.4 ForgotPassword Screen&quot;">​</a></h3><ol><li>1 input <code>email</code>.</li><li>Submit → <code>POST /auth/forgot-password</code> với <code>{ email }</code>.</li><li>Luôn hiển thị thông báo thành công chung (không lộ việc email có tồn tại hay không, theo thông lệ bảo mật) — ví dụ &quot;Nếu email tồn tại, chúng tôi đã gửi hướng dẫn đặt lại mật khẩu&quot;.</li><li>Tùy hình thức backend gửi (xem mục 8 — cần xác nhận link hay OTP): <ul><li>Nếu gửi <strong>link</strong>: user mở email trên điện thoại → tap link → deep link mở thẳng <code>ResetPassword</code> screen với <code>token</code> lấy từ query param của deep link (xem 4.6 cấu hình scheme).</li><li>Nếu gửi <strong>OTP</strong>: điều hướng app sang <code>VerifyOtp</code> screen (purpose=<code>forgotPassword</code>) trước, sau khi verify OTP thành công mới cho vào <code>ResetPassword</code> screen (lúc này <code>token</code> để gửi <code>reset-password</code> có thể chính là OTP code, hoặc một token tạm backend trả về sau verify — cần xác nhận).</li></ul></li></ol><h3 id="_4-5-resetpassword-screen" tabindex="-1">4.5 ResetPassword Screen <a class="header-anchor" href="#_4-5-resetpassword-screen" aria-label="Permalink to &quot;4.5 ResetPassword Screen&quot;">​</a></h3><ol><li>Nếu vào từ deep link: đọc <code>token</code> từ URL, không cho sửa.</li><li>Nếu vào từ flow OTP: <code>token</code> đã có từ bước trước, ẩn field này khỏi UI (không bắt user tự gõ token).</li><li>Input <code>newPassword</code> + <code>confirmPassword</code> (confirm chỉ validate client-side, API không có field confirm).</li><li>Submit → <code>POST /auth/reset-password</code> với <code>{ token, newPassword }</code>.</li><li>Lỗi: token hết hạn/invalid → thông báo rõ &quot;Link đã hết hạn, vui lòng yêu cầu lại&quot; + nút quay về <code>ForgotPassword</code>.</li><li>Thành công → điều hướng về <code>Login</code> kèm toast.</li></ol><h3 id="_4-6-google-oauth-flow-expo-managed-—-dung-expo-web-browser-expo-auth-session" tabindex="-1">4.6 Google OAuth flow (Expo managed — dùng <code>expo-web-browser</code> + <code>expo-auth-session</code>) <a class="header-anchor" href="#_4-6-google-oauth-flow-expo-managed-—-dung-expo-web-browser-expo-auth-session" aria-label="Permalink to &quot;4.6 Google OAuth flow (Expo managed — dùng `expo-web-browser` + `expo-auth-session`)&quot;">​</a></h3><p>Vì đây không phải OAuth chuẩn client-side (PKCE trực tiếp với Google) mà là <strong>backend-driven redirect</strong> (toàn bộ client secret nằm ở backend, giống hệt web), pattern đúng cho Expo managed là:</p><ol><li>App gọi <code>WebBrowser.openAuthSessionAsync(startUrl, returnUrl)</code> trong đó: <ul><li><code>startUrl</code> = <code>{API_BASE_URL}/api/v1/auth/oauth/google</code> (endpoint bắt đầu flow ở mục 3.8).</li><li><code>returnUrl</code> = deep link scheme của app, ví dụ <code>brandhub://oauth-callback</code> (đăng ký qua <code>app.json</code>/<code>app.config.ts</code> field <code>scheme</code>, dùng <code>expo-auth-session</code>&#39;s <code>makeRedirectUri({ scheme: &quot;brandhub&quot;, path: &quot;oauth-callback&quot; })</code> để tạo URI chuẩn cho cả Expo Go và standalone build).</li></ul></li><li>User thấy WebView hệ thống (SFSafariViewController / Chrome Custom Tab) → đăng nhập Google → Google redirect về backend callback → backend redirect tiếp <strong>về <code>returnUrl</code> đã đăng ký</strong> (không phải <code>frontendUrl</code> web mặc định) kèm <code>#token=...</code> hoặc <code>?error=...</code>.</li><li><code>WebBrowser.openAuthSessionAsync</code> tự đóng WebView và trả <code>result.url</code> chứa URL redirect cuối cùng — app tự parse <code>token</code>/<code>error</code> từ đó, <strong>không cần Linking listener riêng</strong> cho trường hợp này (khác với universal link mở app từ ngoài).</li><li>Parse xong: nếu có <code>token</code> → lưu vào SecureStore, gọi tiếp <code>GET /api/v1/auth/me</code> (health-check) rồi tới endpoint Profile đầy đủ (domain khác) để lấy <code>fullName</code>/<code>role</code>/<code>avatarUrl</code>, set Zustand store, vào app chính.</li><li>Nếu có <code>error=ACCOUNT_SUSPENDED</code> → toast riêng &quot;Tài khoản đã bị khóa&quot;; <code>error=oauth_failed</code> hoặc không có token → toast chung &quot;Đăng nhập Google thất bại&quot;.</li><li><strong>Điều kiện chặn trước khi code</strong>: backend phải hỗ trợ redirect về <code>returnUrl</code> custom scheme của mobile thay vì hardcode <code>frontendUrl</code> web — đây là thay đổi backend cần làm trước (ghi ở mục 8), hoặc mobile phải tự host 1 trang callback trung gian (web) để nhận token rồi forward vào app qua deep link — phương án dự phòng nhưng thêm độ phức tạp.</li></ol><h3 id="_4-7-twofactorverify-screen" tabindex="-1">4.7 TwoFactorVerify Screen <a class="header-anchor" href="#_4-7-twofactorverify-screen" aria-label="Permalink to &quot;4.7 TwoFactorVerify Screen&quot;">​</a></h3><ol><li>Nhận <code>twoFactorToken</code> từ bước Login.</li><li>Input 6 số OTP (dùng app Authenticator, theo FR 3.2.7).</li><li>Submit → <code>POST /auth/2fa/verify</code> với <code>{ twoFactorToken, code }</code>.</li><li>Thành công → nhận <code>LoginResponse</code> đầy đủ → lưu token, vào app.</li><li>Lỗi → <code>OTP_INVALID</code>/tương tự → cho nhập lại, không tự động quay về Login (giữ <code>twoFactorToken</code> còn hiệu lực trong thời gian của nó).</li></ol><h3 id="error-loading-states-chung" tabindex="-1">Error/Loading states chung <a class="header-anchor" href="#error-loading-states-chung" aria-label="Permalink to &quot;Error/Loading states chung&quot;">​</a></h3><ul><li>Mọi submit button: disable + spinner khi đang gọi API, tránh double-submit.</li><li>Lỗi network (không có response, timeout): toast &quot;Không thể kết nối, vui lòng thử lại&quot; — khác với lỗi nghiệp vụ có <code>ErrorCode</code>.</li><li>Lỗi theo <code>ErrorCode</code> nên map qua 1 bảng message tiếng Việt tập trung (1 file constants), tái dùng được cho toast ở mọi screen.</li></ul><h2 id="_5-state-storage" tabindex="-1">5. State &amp; storage <a class="header-anchor" href="#_5-state-storage" aria-label="Permalink to &quot;5. State &amp; storage&quot;">​</a></h2><ul><li><strong>Token storage</strong>: dùng <code>expo-secure-store</code> (đã có trong <code>package.json</code>, đúng như README mô tả &quot;Tokens stored in expo-secure-store... Auto-refresh on 401&quot;). Lưu 2 key riêng: <code>accessToken</code>, <code>refreshToken</code>. Không lưu <code>twoFactorToken</code> vào SecureStore (sống ngắn, chỉ cần trong memory/Zustand state, mất khi app bị kill giữa chừng là chấp nhận được — user login lại).</li><li><strong>Zustand store</strong> (<code>useAuthStore</code> — mirror ý tưởng <code>authStore</code> ở web):<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>\n<span class="line"><span>  accessToken: string | null,</span></span>\n<span class="line"><span>  refreshToken: string | null,</span></span>\n<span class="line"><span>  user: { userId, email, fullName, role, workspaceId, avatarUrl } | null,   // field đầy đủ lấy từ Profile API, ngoài scope DTO auth thuần</span></span>\n<span class="line"><span>  lastUsedPlatform: &quot;email&quot; | &quot;google&quot; | null,   // FR 3.2.8, lưu cả vào SecureStore/AsyncStorage để tồn tại qua session</span></span>\n<span class="line"><span>  isAuthenticated: boolean,</span></span>\n<span class="line"><span>  setAuth(user, accessToken, refreshToken): void,</span></span>\n<span class="line"><span>  setTokens(accessToken, refreshToken): void,     // dùng khi chỉ có token, chưa có profile (OAuth callback, giống web)</span></span>\n<span class="line"><span>  clearAuth(): void,</span></span>\n<span class="line"><span>}</span></span></code></pre></div></li><li><strong>TanStack Query hooks cần có</strong>: <ul><li><code>useLoginMutation</code> — gọi <code>POST /auth/login</code>, side-effect set Zustand store khi không cần 2FA.</li><li><code>useRegisterMutation</code> — <code>POST /auth/register</code>.</li><li><code>useVerifyOtpMutation</code>, <code>useResendOtpMutation</code>.</li><li><code>useForgotPasswordMutation</code>, <code>useResetPasswordMutation</code>.</li><li><code>useVerifyTwoFactorMutation</code>.</li><li><code>useLogoutMutation</code> — gọi <code>POST /auth/logout</code>, luôn <code>clearAuth()</code> ở <code>onSettled</code> (dù API lỗi vẫn phải xóa token local).</li><li><code>useMeQuery</code> (optional, cho health-check sau OAuth) — <code>GET /auth/me</code>.</li><li>Refresh token <strong>không</strong> nên là 1 TanStack hook thông thường — nó chạy trong Axios response interceptor (401 → gọi refresh → retry request gốc), đúng theo mô tả README hiện tại, giữ nguyên pattern đó.</li></ul></li></ul><h2 id="_6-business-rules-đac-biet" tabindex="-1">6. Business rules đặc biệt <a class="header-anchor" href="#_6-business-rules-đac-biet" aria-label="Permalink to &quot;6. Business rules đặc biệt&quot;">​</a></h2><ul><li><strong>Email case-insensitive ở local-part</strong> (FR 3.2.1): <code>User@gmail.com</code> và <code>user@gmail.com</code> là cùng 1 account — đây là rule backend xử lý, mobile chỉ cần <strong>không tự uppercase/lowercase email khi hiển thị lại</strong> để tránh gây hiểu nhầm, nhưng khi submit để nguyên input user gõ (backend chịu trách nhiệm normalize).</li><li><strong>Sign Up bắt buộc OTP, Sign In không cần</strong> — không được tự động đăng nhập ngay sau register thành công dù có <code>userId</code> trả về.</li><li><strong>Change Password yêu cầu confirm 2 lần hoặc modal</strong> (FR 3.2.5) — không thuộc G1 nhưng nếu sau này thêm, nhớ áp dụng cùng rule UX.</li><li><strong>2FA chỉ còn QR + OTP</strong>, không còn copy secret key / backup codes (FR 3.2.7) — G1 mobile chỉ cần implement màn <strong>Verify</strong> (nhập OTP khi được yêu cầu lúc login), không cần implement Setup (quét QR) ở G1.</li><li><strong>Last used platform phải persist qua logout</strong> (FR 3.2.8) — không xóa field này trong <code>clearAuth()</code>, chỉ xóa token/user.</li><li><strong>Password rule validate client-side trước khi submit</strong> (để UX nhanh, backend vẫn validate lại): tối thiểu 8 ký tự + có ít nhất 1 số (từ <code>@Pattern</code> và <code>@Size</code> trong <code>RegisterRequest</code>/<code>ResetPasswordRequest</code>).</li><li><strong>Không tiết lộ email có tồn tại hay không</strong> ở Forgot Password — luôn trả message thành công chung phía UI dù backend response thế nào (đây là rule UX chuẩn, chưa thấy backend code quyết định rõ nhưng nên áp dụng phòng hộ).</li></ul><h2 id="_7-viec-khong-lam-o-g1" tabindex="-1">7. Việc KHÔNG làm ở G1 <a class="header-anchor" href="#_7-viec-khong-lam-o-g1" aria-label="Permalink to &quot;7. Việc KHÔNG làm ở G1&quot;">​</a></h2><ul><li>Setup/bật mới 2FA (scan QR) — chỉ làm Verify khi đã bật từ trước (có thể bật qua web).</li><li>Disable 2FA.</li><li>Change Password (khi đã đăng nhập, không phải Forgot Password).</li><li>Deactivate Account.</li><li>Link/Unlink Phone, Link/Unlink OAuth provider (Settings/Connections) — ngoại trừ đọc để hiển thị trạng thái nếu cần ở màn Settings (thuộc domain khác).</li><li>Profile đầy đủ (View/Update User Profile, Client Profile) — thuộc FR 3.3, domain riêng, không viết trong G1 này.</li><li>Background/offline token refresh khi app bị kill (ngoài phạm vi theo quyết định chung ở <code>mobile-app-plan.md</code> mục 1 — foreground only giai đoạn đầu).</li></ul><h2 id="_8-rui-ro-cau-hoi-mo-—-đa-xac-nhan-bang-code-that-2026-10-22" tabindex="-1">8. Rủi ro / câu hỏi mở — đã xác nhận bằng code thật (2026-10-22) <a class="header-anchor" href="#_8-rui-ro-cau-hoi-mo-—-đa-xac-nhan-bang-code-that-2026-10-22" aria-label="Permalink to &quot;8. Rủi ro / câu hỏi mở — đã xác nhận bằng code thật (2026-10-22)&quot;">​</a></h2><ol><li><p><strong>Google OAuth redirect target cho mobile — ĐÃ SỬA BACKEND (2026-10-22).</strong> Thêm query param <code>client</code> cho <code>GET /oauth/google</code> (<code>?client=mobile</code>) → <code>GoogleOAuthController.redirect()</code> gọi <code>GoogleOAuthService.buildAuthorizationUrlForClient(&quot;mobile&quot;)</code> thay vì <code>buildAuthorizationUrl()</code> mặc định. Flag này được nhét vào OAuth <code>state</code> string lưu Redis (format mới <code>provider|linkingUserId|client</code>, field thứ 3 thêm vào <code>OAuthService</code>), đọc lại ở <code>handleCallback()</code> thành <code>CallbackResult.isMobileClient()</code>. Controller chọn redirect base qua <code>callbackBaseUrl(isMobileClient, webPath)</code>: nếu <code>isMobileClient=true</code> và <code>app.mobile-redirect-uri</code> có cấu hình → dùng thẳng giá trị đó (deep link <code>brandhub://oauth-callback</code>, không thêm path); ngược lại giữ hành vi web cũ <code>{frontendUrl}{webPath}</code>. <strong>Việc còn lại phía backend config</strong>: set giá trị thật cho <code>app.mobile-redirect-uri=brandhub://oauth-callback</code> trong <code>application.yml</code>/biến môi trường môi trường mobile dùng — code đã sẵn sàng đọc field này qua <code>AppProperties.getMobileRedirectUri()</code>, nhưng nếu không set thì mobile vẫn fallback về <code>frontendUrl</code> web như cũ (an toàn, không crash, chỉ là chưa hoạt động đúng cho mobile). <strong>Giới hạn đã biết</strong>: nhánh lỗi (<code>businessFailure</code>, <code>loginFailure</code> khi <code>BusinessException</code>/<code>RestClientException</code> xảy ra) chưa đọc được <code>isMobileClient</code> vì <code>state</code> đã bị <code>getAndDelete</code> trước khi exception ném ra trong <code>handleCallback()</code> — các lỗi đó luôn redirect về web <code>frontendUrl</code>. Mobile code phía app cần tự coi &quot;redirect về web URL thay vì deep link app&quot; là 1 dạng lỗi gián tiếp (không bao giờ thấy redirect quay lại app) và xử lý timeout hợp lý ở <code>WebBrowser.openAuthSessionAsync</code>, không chỉ trông chờ mọi lỗi đều quay về app.</p></li><li><p><strong>BA ghi Google OAuth &quot;chưa chạy được&quot; trên web — XÁC NHẬN: KHÔNG phải trạng thái lỗi hiện tại, ghi chú đã cũ.</strong> Đọc <code>GoogleOAuthController.java</code> đầy đủ: flow có xử lý đủ 3 nhánh (<code>OAUTH_EMAIL_MISMATCH</code>/<code>OAUTH_ALREADY_LINKED</code> link-mode, <code>ACCOUNT_SUSPENDED</code> riêng biệt, success kèm set cookie + fragment token), code hoàn chỉnh, không thấy TODO/FIXME/lỗi rõ ràng nào trong controller lẫn <code>AppProperties</code>. Dòng ghi chú ở BA doc (dòng 17 <code>02-authentication-profile.md</code>) là input do BA note lại từ báo cáo tại thời điểm viết doc, không phải trạng thái code đọc được hôm nay — coi là <strong>đã fix hoặc chưa bao giờ đúng ở mức backend</strong>, nhưng <strong>vẫn cần test tay thật trên môi trường chạy</strong> (không đọc code suy ra được lỗi integration thật với Google) trước khi đóng G1.</p></li><li><p><strong>Refresh token cookie vs body — XÁC NHẬN cả 2 phần của câu hỏi.</strong></p><ul><li>(a) <code>AuthController.login()</code> (dòng 52-74) và <code>.refresh()</code> (dòng 76-103): response <code>LoginResponse</code> body <strong>luôn</strong> chứa <code>accessToken</code>/<code>refreshToken</code> đầy đủ khi không cần 2FA — cookie chỉ là <strong>thêm</strong>, không phải thay thế. Mobile đọc <code>refreshToken</code> từ body là đúng và được backend hỗ trợ sẵn, không cần xin thêm gì.</li><li>(b) <code>AuthController.logout()</code> — <strong>ĐÃ SỬA BACKEND (2026-10-22)</strong>: thêm <code>@RequestBody(required = false) RefreshTokenRequest request</code>, cùng pattern với <code>/refresh</code> — ưu tiên cookie nếu có, fallback đọc <code>request.refreshToken()</code> từ body nếu không. Mobile giờ gọi <code>POST /auth/logout</code> kèm body <code>{ &quot;refreshToken&quot;: &quot;...&quot; }</code> để revoke đúng token, không chỉ xóa local.</li></ul></li><li><p><strong>Forgot Password gửi link hay OTP — XÁC NHẬN: chỉ gửi LINK, không có nhánh OTP.</strong> Đọc <code>AuthServiceImpl.forgotPassword()</code> (dòng 331-354) + <code>MailServiceImpl.sendPasswordResetEmail()</code>: sinh <code>token</code> random 32-byte hex, lưu Redis TTL = <code>appProperties.getPasswordResetTtlSeconds()</code> (default 3600s = 1h), gửi email HTML với nút bấm link <code>{frontendUrl}/reset-password?token={token}</code>. <strong>Không có code nào sinh/gửi OTP 6 số cho forgot-password flow</strong> — câu chữ BA &quot;gửi link HOẶC mã OTP&quot; chỉ là tả 2 khả năng thiết kế, thực tế code chọn <strong>link only</strong>. → Mục 4.4-4.5 trong spec này <strong>chỉ cần giữ nhánh deep link</strong>, bỏ hẳn nhánh OTP cho Reset Password (nhánh OTP ở 4.4 bước 4 &quot;Nếu gửi OTP&quot; không áp dụng — xoá khỏi UI/code mobile để tránh làm thừa màn hình). Token sống 1h, dùng 1 lần (<code>resetPassword()</code> dòng 356-368 xoá key Redis ngay khi dùng, dùng lại báo <code>RESET_TOKEN_USED</code>).</p></li><li><p><strong>Deep link scheme chưa đăng ký — vẫn mở, cần quyết định của team mobile</strong> (không đọc được từ backend, đây là việc phía <code>brandhub-mobile-app</code> tự quyết <code>app.json</code>). Giữ nguyên câu hỏi: chọn <code>scheme</code> (đề xuất <code>brandhub</code>), và quyết định có cần Universal Links/App Links thật hay dùng custom scheme thuần (ảnh hưởng link reset-password mở từ email client Android/iOS một số hãng có thể chặn custom scheme — cần test thật trên thiết bị, không tìm thấy cấu hình Universal Link nào trong repo hiện tại).</p></li><li><p><strong>Rate limit resend OTP — XÁC NHẬN: cố định 60 giây, không cấu hình được.</strong><code>AuthServiceImpl.resendOtp()</code> dòng 163-183: set Redis key rate-limit với TTL hard-code <code>Duration.ofSeconds(60)</code> (dòng 183, comment &quot;1-min cooldown&quot; ngay trong code). Không có field trả về <code>retryAfter</code> trong response (<code>ApiResponse&lt;Void&gt;</code>), nên mobile <strong>phải tự đếm ngược 60s cố định ở client</strong> sau khi gọi <code>resend-otp</code> thành công — không cần hỏi backend, giá trị đã chốt cứng, chỉ cần client code đúng số 60.</p></li><li><p><strong><code>/api/v1/auth/me</code> vs Users Profile đầy đủ — XÁC NHẬN path chính xác: <code>GET /api/v1/users/me</code>.</strong><code>UserController.java</code> dòng 18-19, 28-35: <code>@RequestMapping(&quot;/api/v1/users&quot;)</code>, endpoint <code>GET /me</code> nhận <code>@AuthenticationPrincipal AuthenticatedUser</code>, trả <code>UserProfileResponse</code> qua <code>userService.getUserProfile()</code>. Đây đúng là API domain Profile (ngoài scope G1) mà mobile phải gọi sau OAuth/login để có <code>fullName</code>/<code>avatarUrl</code>/<code>role</code> — xác nhận không trùng với <code>/api/v1/auth/me</code> (<code>MeResponse</code>, chỉ có <code>userId/email/phone/hasPassword/linkedProviders/twoFactorEnabled</code>). Domain Profile viết doc riêng có thể dùng thẳng path này, không cần đoán nữa.</p></li></ol>',67)])])}const p=o(i,[["render",a]]);export{u as __pageData,p as default};
